    const nps = total > 0 ? Math.round(((promoters - detractors) / total) * 100) : 0;
    const stats = {
      total_reviews: total,
      avg_rating: parseFloat(avgRows[0].avg) || 0,
      response_rate: parseFloat(respRows[0].cast) || 0,
      pending_issues: parseInt(pendingRows[0].count, 10),
      nps: nps
    };
